<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Snake Game</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: #1a1a1a;
            color: #fff;
            font-family: Arial, sans-serif;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            padding: 20px;
        }

        .container {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 20px;
        }

        h1 {
            font-size: 32px;
            margin-bottom: 10px;
        }

        #score {
            font-size: 20px;
            font-weight: bold;
        }

        #snake {
            border: 2px solid #fff;
            background-color: #0a0a0a;
            display: block;
            width: 400px;
            height: 400px;
        }

        .controls {
            display: flex;
            gap: 10px;
        }

        button {
            padding: 10px 20px;
            font-size: 16px;
            background-color: #333;
            color: #fff;
            border: 2px solid #555;
            cursor: pointer;
            border-radius: 5px;
            transition: background-color 0.3s;
        }

        button:hover {
            background-color: #555;
        }

        button:active {
            background-color: #777;
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Snake</h1>
        <div id="score">Score: 0</div>
        <canvas id="snake" width="400" height="400"></canvas>
        <div class="controls">
            <button id="start">Start</button>
            <button id="pause">Pause</button>
            <button id="reset">Reset</button>
        </div>
    </div>

    <script>
        const canvas = document.getElementById('snake');
        const ctx = canvas.getContext('2d');
        const scoreDisplay = document.getElementById('score');
        const startBtn = document.getElementById('start');
        const pauseBtn = document.getElementById('pause');
        const resetBtn = document.getElementById('reset');

        const CELL_SIZE = 20;
        const GRID_WIDTH = 20;
        const GRID_HEIGHT = 20;

        let gameState = {
            snake: [[10, 10], [9, 10], [8, 10]],
            food: [15, 15],
            direction: 'right',
            nextDirection: 'right',
            score: 0,
            alive: true,
            gameRunning: false,
            gameLoopId: null
        };

        function isValidPosition(x, y) {
            return x >= 0 && x < GRID_WIDTH && y >= 0 && y < GRID_HEIGHT;
        }

        function getRandomFreeCell() {
            let x, y;
            const snakeSet = new Set(gameState.snake.map(cell => `${cell[0]},${cell[1]}`));
            do {
                x = Math.floor(Math.random() * GRID_WIDTH);
                y = Math.floor(Math.random() * GRID_HEIGHT);
            } while (snakeSet.has(`${x},${y}`));
            return [x, y];
        }

        function reset() {
            if (gameState.gameLoopId) {
                clearInterval(gameState.gameLoopId);
                gameState.gameLoopId = null;
            }
            gameState.snake = [[10, 10], [9, 10], [8, 10]];
            gameState.food = getRandomFreeCell();
            gameState.direction = 'right';
            gameState.nextDirection = 'right';
            gameState.score = 0;
            gameState.alive = true;
            gameState.gameRunning = false;
            scoreDisplay.textContent = 'Score: 0';
            startBtn.textContent = 'Start';
            pauseBtn.textContent = 'Pause';
            draw();
        }

        function setDir(direction) {
            const opposite = {
                'up': 'down',
                'down': 'up',
                'left': 'right',
                'right': 'left'
            };
            if (opposite[direction] !== gameState.direction) {
                gameState.nextDirection = direction;
            }
        }

        function tick() {
            if (!gameState.alive) return;

            gameState.direction = gameState.nextDirection;

            const head = gameState.snake[0];
            let newHead;

            switch (gameState.direction) {
                case 'up':
                    newHead = [head[0], head[1] - 1];
                    break;
                case 'down':
                    newHead = [head[0], head[1] + 1];
                    break;
                case 'left':
                    newHead = [head[0] - 1, head[1]];
                    break;
                case 'right':
                    newHead = [head[0] + 1, head[1]];
                    break;
            }

            if (!isValidPosition(newHead[0], newHead[1])) {
                gameState.alive = false;
                return;
            }

            if (gameState.snake.some(cell => cell[0] === newHead[0] && cell[1] === newHead[1])) {
                gameState.alive = false;
                return;
            }

            gameState.snake.unshift(newHead);

            if (newHead[0] === gameState.food[0] && newHead[1] === gameState.food[1]) {
                gameState.score++;
                scoreDisplay.textContent = `Score: ${gameState.score}`;
                gameState.food = getRandomFreeCell();
            } else {
                gameState.snake.pop();
            }

            draw();
        }

        function setFood(x, y) {
            gameState.food = [x, y];
            draw();
        }

        function snake() {
            return gameState.snake.map(cell => [...cell]);
        }

        function food() {
            return [...gameState.food];
        }

        function alive() {
            return gameState.alive;
        }

        function score() {
            return gameState.score;
        }

        function draw() {
            ctx.fillStyle = '#0a0a0a';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            ctx.strokeStyle = '#1a1a1a';
            ctx.lineWidth = 1;
            for (let i = 0; i <= GRID_WIDTH; i++) {
                ctx.beginPath();
                ctx.moveTo(i * CELL_SIZE, 0);
                ctx.lineTo(i * CELL_SIZE, canvas.height);
                ctx.stroke();
            }
            for (let i = 0; i <= GRID_HEIGHT; i++) {
                ctx.beginPath();
                ctx.moveTo(0, i * CELL_SIZE);
                ctx.lineTo(canvas.width, i * CELL_SIZE);
                ctx.stroke();
            }

            gameState.snake.forEach((cell, index) => {
                ctx.fillStyle = index === 0 ? '#00ff00' : '#00cc00';
                ctx.fillRect(cell[0] * CELL_SIZE + 1, cell[1] * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);
            });

            ctx.fillStyle = '#ff0000';
            ctx.fillRect(gameState.food[0] * CELL_SIZE + 1, gameState.food[1] * CELL_SIZE + 1, CELL_SIZE - 2, CELL_SIZE - 2);
        }

        window.game = {
            w: GRID_WIDTH,
            h: GRID_HEIGHT,
            reset,
            tick,
            setDir,
            setFood,
            snake,
            food,
            alive,
            score
        };

        function startGameLoop() {
            gameState.gameLoopId = setInterval(() => {
                if (gameState.gameRunning && gameState.alive) {
                    tick();
                } else if (!gameState.alive) {
                    clearInterval(gameState.gameLoopId);
                    gameState.gameLoopId = null;
                    gameState.gameRunning = false;
                    startBtn.textContent = 'Start';
                }
            }, 100);
        }

        startBtn.addEventListener('click', () => {
            if (!gameState.gameRunning) {
                if (!gameState.alive) {
                    reset();
                }
                gameState.gameRunning = true;
                startBtn.textContent = 'Running...';
                if (!gameState.gameLoopId) {
                    startGameLoop();
                }
            }
        });

        pauseBtn.addEventListener('click', () => {
            if (gameState.gameRunning) {
                gameState.gameRunning = false;
                startBtn.textContent = 'Resume';
            }
        });

        resetBtn.addEventListener('click', () => {
            reset();
        });

        document.addEventListener('keydown', (e) => {
            switch (e.key) {
                case 'ArrowUp':
                    e.preventDefault();
                    setDir('up');
                    break;
                case 'ArrowDown':
                    e.preventDefault();
                    setDir('down');
                    break;
                case 'ArrowLeft':
                    e.preventDefault();
                    setDir('left');
                    break;
                case 'ArrowRight':
                    e.preventDefault();
                    setDir('right');
                    break;
            }
        });

        reset();
    </script>
</body>
</html>
